function startShowcase() {
  if (showcase.playing) return;
  showcase.playing = true;
  showcase.t = 0;
  for (const k in fired) delete fired[k];
  if (fly.active) exitFly();
  controls.enabled = false;
  $('playBtn').blur();
  $('hud').classList.add('hidden');
  $('playBtn').classList.add('hidden');
  document.body.classList.add('bars-on');
  // hard cut to black, then a slow fade-in onto the opening shot
  const fader = $('fader');
  fader.style.transition = 'none';
  fader.style.opacity = '1';
  requestAnimationFrame(() => requestAnimationFrame(() => {
    fader.style.transition = 'opacity 1.4s ease';
    fader.style.opacity = '0';
  }));
}
